def ncr_modp(n, r, p):
    from math import gcd
    from functools import reduce
    def mult_mod(a, b, m):
        return (a * b) % m

    def extended_gcd(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            g, y, x = extended_gcd(b % a, a)
            return (g, x - (b // a) * y, y)

    def mod_inverse(a, m):
        g, x, _ = extended_gcd(a, m)
        if g != 1:
            raise Exception('Modular inverse does not exist')
        else:
            return x % m

    def ncr_modp_helper(n, r, p):
        if r == 0:
            return 1
        if r == n:
            return 1
        if r > n:
            return 0
        if r < 0:
            return 0
        num = reduce(mult_mod, range(n, n - r, -1), 1)
        den = reduce(mult_mod, range(1, r + 1), 1)
        num_inv = mod_inverse(num, p)
        return (num_inv * den) % p

    return ncr_modp_helper(n, r, p)
