        if r == 0:
            return 1
        if r == n:
            return 1
        if r > n:
            return 0
        if r < 0:
            return 0
        num = reduce(mult_mod, range(n, n - r, -1), 1)
        den = reduce(mult_mod, range(1, r + 1), 1)
        num_inv = mod_inverse(num, p)
        return (num_inv * den) % p

    return ncr_modp_helper(n, r, p)
